package com.agriconnect.order;import java.util.*;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component class ShipmentEventConsumer{private final JdbcClient db;ShipmentEventConsumer(JdbcClient d){db=d;}@RabbitListener(queues="order.shipment-events")@Transactional void consume(Map<String,Object>event){UUID eventId=UUID.fromString(String.valueOf(event.get("eventId")));if(db.sql("select count(*) from processed_events where event_id=:id").param("id",eventId).query(Long.class).single()>0)return;Map<?,?>p=(Map<?,?>)event.get("payload");long order=((Number)p.get("orderId")).longValue();String type=String.valueOf(event.get("eventType"));String status=switch(type){case"ShipmentShippingStarted"->"SHIPPING";case"ShipmentDelivered"->"DELIVERED";case"ShipmentFailed"->"CANCELLED";default->null;};if(status!=null)db.sql("update orders set status=:s,return_state=case when :s='CANCELLED' then 'ADMIN_REVIEW' else return_state end where id=:id and status<>:s").param("s",status).param("id",order).update();db.sql("insert into processed_events(event_id)values(:id)").param("id",eventId).update();}}
